import{_ as s,o as n,c as e,a2 as t}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"本地配置SSL证书","description":"","frontmatter":{"title":"本地配置SSL证书","author":"麻瓜【码瓜】","date":"2024-07-03"},"headers":[],"relativePath":"posts/mkcert.md","filePath":"posts/mkcert.md","lastUpdated":1794582610000}'),p={name:"posts/mkcert.md"};function i(l,a,c,o,d,r){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="本地配置ssl证书" tabindex="-1">本地配置SSL证书 <a class="header-anchor" href="#本地配置ssl证书" aria-label="Permalink to &quot;本地配置SSL证书&quot;">​</a></h1><h2 id="安装支持包" tabindex="-1">安装支持包 <a class="header-anchor" href="#安装支持包" aria-label="Permalink to &quot;安装支持包&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apt install wget libnss3-tools -y</span></span></code></pre></div><h2 id="下载mkcert" tabindex="-1">下载Mkcert <a class="header-anchor" href="#下载mkcert" aria-label="Permalink to &quot;下载Mkcert&quot;">​</a></h2><p>建议挂代理下载<br><code>https://github.moeyy.xyz/</code><br><code>https://mirror.ghproxy.com/</code><br><code>https://gitdl.cn/</code></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wget --no-check-certificate https://github.com/FiloSottile/mkcert/releases/download/v1.4.3/mkcert-v1.4.3-linux-amd64</span></span></code></pre></div><h2 id="添加到系统路径" tabindex="-1">添加到系统路径 <a class="header-anchor" href="#添加到系统路径" aria-label="Permalink to &quot;添加到系统路径&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mv mkcert-v1.4.3-linux-amd64 /usr/bin/mkcert</span></span></code></pre></div><h2 id="设置执行权限" tabindex="-1">设置执行权限 <a class="header-anchor" href="#设置执行权限" aria-label="Permalink to &quot;设置执行权限&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chmod +x /usr/bin/mkcert</span></span></code></pre></div><h2 id="验证-mkcert-版本" tabindex="-1">验证 Mkcert 版本 <a class="header-anchor" href="#验证-mkcert-版本" aria-label="Permalink to &quot;验证 Mkcert 版本&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkcert -version</span></span></code></pre></div><p>您应该看到以下输出：<br><code>v1.4.3</code></p><h2 id="生成本地-ca" tabindex="-1">生成本地 CA <a class="header-anchor" href="#生成本地-ca" aria-label="Permalink to &quot;生成本地 CA&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkcert -install</span></span></code></pre></div><p>您应该看到以下输出：<br><code>Created a new local CA ????</code><br><code>The local CA is now installed in the system trust store! ??</code><br><code>The local CA is now installed in the Firefox and/or Chrome/Chromium trust store (requires browser restart)! ????</code><br> 您可以使用以下命令检查 CA 证书的路径：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkcert -CAROOT</span></span></code></pre></div><p>您应该看到以下输出：<br><code>/root/.local/share/mkcert</code></p><h2 id="生成本地网站证书" tabindex="-1">生成本地网站证书 <a class="header-anchor" href="#生成本地网站证书" aria-label="Permalink to &quot;生成本地网站证书&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkcert domain.com</span></span></code></pre></div><p>您应该看到以下输出：<br><code>Created a new certificate valid for the following names ????</code><br><code> - &quot;domain.com&quot;</code><br><code>The certificate is at &quot;./domain.com.pem&quot; and the key at &quot;./domain.com-key.pem&quot; ?</code><br><code>It will expire on 1 November 2023 ????</code></p><p>生成的证书在当前目录下<br><code>domain.com.pem</code><br><code>domain.com-key.pem</code></p><h2 id="启用生成的证书" tabindex="-1">启用生成的证书 <a class="header-anchor" href="#启用生成的证书" aria-label="Permalink to &quot;启用生成的证书&quot;">​</a></h2><p>将生成的证书文件复制到<code>/etc/ssl/</code>目录</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cp domain.com* /etc/ssl/</span></span></code></pre></div><h2 id="修改nginx配置文件" tabindex="-1">修改nginx配置文件 <a class="header-anchor" href="#修改nginx配置文件" aria-label="Permalink to &quot;修改nginx配置文件&quot;">​</a></h2><p><code>/etc/nginx/conf.d/nginx.conf</code><br> 配置方法参考下面的代码</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#/etc/nginx/conf.d/nginx.conf</span></span>
<span class="line"><span>server{</span></span>
<span class="line"><span>        root /var/www/[ROOTDIR];</span></span>
<span class="line"><span>        index index.php index.html index.htm index.nginx-debian.html;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        server_name [DOMAIN].net;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        location / {</span></span>
<span class="line"><span>                try_files $uri $uri/ /index.php?$args;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        location ~ \\.php$ {</span></span>
<span class="line"><span>                include snippets/fastcgi-php.conf;</span></span>
<span class="line"><span>                fastcgi_pass unix:/run/php/php7.4-fpm.sock;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    listen 443 ssl; </span></span>
<span class="line"><span>    ssl_certificate /etc/ssl/[DOMAIN].pem; </span></span>
<span class="line"><span>    ssl_certificate_key /etc/ssl/[DOMAIN]-key.pem; </span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>server{</span></span>
<span class="line"><span>    if ($host = www.[DOMAIN].net) {</span></span>
<span class="line"><span>        return 301 https://$host$request_uri;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    if ($host = [DOMAIN].net) {</span></span>
<span class="line"><span>        return 301 https://$host$request_uri;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>        listen 80 ;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        server_name [DOMAIN].net www.[DOMAIN].net;</span></span>
<span class="line"><span>    return 404; </span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="测试nginx配置文件" tabindex="-1">测试nginx配置文件 <a class="header-anchor" href="#测试nginx配置文件" aria-label="Permalink to &quot;测试nginx配置文件&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nginx -t</span></span></code></pre></div><h2 id="重启-nginx-服务" tabindex="-1">重启 Nginx 服务 <a class="header-anchor" href="#重启-nginx-服务" aria-label="Permalink to &quot;重启 Nginx 服务&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>systemctl restart nginx</span></span></code></pre></div>`,32)])])}const b=s(p,[["render",i]]);export{u as __pageData,b as default};
